using System;
using System.Text.RegularExpressions;

public class IBANValidator
{
    // Basic format check for IBAN
    public static bool CheckFormat(string iban)
    {
        // Regular expression for IBAN format
        string pattern = @"^[A-Z]{2}[0-9]{2}[A-Z]{2}[0-9]{2}[A-Z]{2}[0-9]{2}[A-Z]{2}[0-9]{2}[A-Z]{2}[0-9]{2}$";
        Regex regex = new Regex(pattern);
        return regex.IsMatch(iban);
    }

    // Unit tests for IBAN validation
    public static void Main(string[] args)
    {
        // Test valid IBANs
        Console.WriteLine("Valid IBANs:");
        Console.WriteLine(CheckFormat("GB12345678901234567890")); // Should return true
        Console.WriteLine(CheckFormat("GB12345678901234567890")); // Should return true
        Console.WriteLine(CheckFormat("GB12345678901234567890")); // Should return true

        // Test invalid IBANs
        Console.WriteLine("\nInvalid IBANs:");
        Console.WriteLine(CheckFormat("GB12345678901234567890")); // Should return false
        Console.WriteLine(CheckFormat("GB123456789012345678901")); // Should return false
        Console.WriteLine(CheckFormat("GB123456789012345678901")); // Should return false
    }
}
